// The offline service worker of one app: keeps every file the app needs in Cache Storage, so an
// installed app (or a page opened before) starts and plays without a network.
// GENERATED by tools/sw-build.js from tools/sw-template.js — never edit a <folder>/sw.js by hand:
// change the template and run `node tools/sw-build.js`. Registered by update.js (AppUpdate.watch).
//
// - Install: downloads the whole file list below into a cache named after this version. Every
//   change to an app's files changes VERSION, so the browser installs the new worker after a
//   deploy and the app is complete offline again.
// - The page (a navigation): network first, so a deploy is seen at once; the cached copy when the
//   network fails or takes longer than PAGE_TIMEOUT_MS.
// - A file with ?v=N: from the cache, else from the network (then cached) — a new N is a new file.
// - A file without ?v: from the cache at once, refreshed from the network for the next start.
// - Offline and not cached under this exact address: the same file under any ?v= it was cached.
//
// The worker serves only its own folder (the scope). Cache names start with the scope's path,
// e.g. "/ivan/lift-logic/offline.<version>": every app on the shared origin keeps its own and
// deletes only its own old ones.

const VERSION = "dc369166eeca";
// Paths relative to this folder; './' is the page itself, ?v=N as the page links them.
